//! `client-config.json`: the only configuration the web app is built with. Public keys and what is
//! derived from them; nothing else can be added without a new field here, and a test ties the
//! public keys of the schema to this struct.

use std::collections::BTreeMap;

use schemars::JsonSchema;
use serde::Serialize;

use crate::modules::ModuleStatus;
use crate::settings::{GradingScale, Language, Settings};

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct ClientConfig {
    /// The Vumlo release the file was generated by.
    pub version: String,
    /// Where the web app reaches the API: `server.public_origin` + `/api/v1`.
    pub api_url: String,
    /// The keys marked `public` in the configuration schema.
    pub public: PublicConfig,
    /// Every optional module of this build line and whether it is on.
    pub modules: BTreeMap<String, ModuleStatus>,
    /// The enabled modules that have UI in the web app: only these are built into the web bundle.
    pub web_modules: Vec<String>,
    /// The generated logo, relative to the generated directory. Absent without `institution.logo`.
    pub logo: Option<String>,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct PublicConfig {
    pub server: PublicServer,
    pub institution: PublicInstitution,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct PublicServer {
    pub public_origin: String,
}

#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct PublicInstitution {
    pub name: String,
    pub short_name: String,
    pub language: Language,
    /// An IANA zone name, e.g. `Europe/Kyiv`.
    pub time_zone: String,
    pub grading_scale: GradingScale,
}

impl ClientConfig {
    pub fn new(settings: &Settings, version: &str, logo: Option<String>) -> Self {
        let institution = &settings.institution;
        Self {
            version: version.to_owned(),
            api_url: api_url(settings),
            public: PublicConfig {
                server: PublicServer {
                    public_origin: settings.server.public_origin.clone(),
                },
                institution: PublicInstitution {
                    name: institution.name.clone(),
                    short_name: institution.short_name.clone(),
                    language: institution.language,
                    time_zone: institution.time_zone.name().to_owned(),
                    grading_scale: institution.grading_scale,
                },
            },
            modules: settings.module_state.statuses(),
            web_modules: crate::modules::known_modules()
                .iter()
                .filter(|m| m.web && settings.module_state.is_enabled(m.name))
                .map(|m| m.name.to_owned())
                .collect(),
            logo,
        }
    }
}

/// The API base URL, derived once from `[server].public_origin`.
pub fn api_url(settings: &Settings) -> String {
    format!("{}/api/v1", settings.server.public_origin)
}

